import { Source } from './source';
import { mapEvent } from './mapper';
export class EventService {
  constructor(private readonly source: Source, private readonly mapper: (value: string) => string = mapEvent) {}
  async *stream(): AsyncGenerator<string> {
    const lease = await this.source.open();
    let closed = false;
    try {
      for (;;) {
        const value = await lease.read();
        if (value === null) break;
        yield this.mapper(value);
      }
    } catch (error) {
      // Read, mapper or consumer-injected failure: close once, keep the original error.
      closed = true;
      try { await lease.close(); } catch { /* original error wins */ }
      throw error;
    } finally {
      // Normal exhaustion or consumer break/return: close failures propagate.
      if (!closed) {
        closed = true;
        await lease.close();
      }
    }
  }
}
