const assert = require('node:assert/strict');
const { EventService } = require('../.build/service');
function make(values, opts = {}) {
  const log = { opens: 0, reads: 0, closes: 0 };
  const source = { open: async () => { log.opens++; return {
    read: async () => { log.reads++; if (opts.readFail && log.reads === opts.readFail) throw new Error('read'); return values.shift() ?? null; },
    close: async () => { log.closes++; if (opts.closeFail) throw new Error('close'); } }; } };
  return { log, source };
}
async function main() {
  { // unopened generator
    const { log, source } = make(['a']); const g = new EventService(source).stream();
    await g.return(undefined); assert.deepEqual(log, { opens: 0, reads: 0, closes: 0 });
  }
  { // lazy, no read-ahead, break
    const { log, source } = make(['a', 'b', 'c']); const g = new EventService(source).stream();
    assert.equal(log.opens, 0);
    assert.deepEqual(await g.next(), { value: 'A', done: false });
    assert.equal(log.reads, 1);
    await g.return(undefined); assert.equal(log.closes, 1);
  }
  { // exhaustion
    const { log, source } = make(['a']); const out = [];
    for await (const v of new EventService(source).stream()) out.push(v);
    assert.deepEqual(out, ['A']); assert.equal(log.reads, 2); assert.equal(log.closes, 1);
  }
  { // read failure, close also fails -> read error
    const { log, source } = make(['a'], { readFail: 2, closeFail: true });
    const g = new EventService(source).stream(); await g.next();
    await assert.rejects(g.next(), /read/); assert.equal(log.closes, 1);
  }
  { // mapper failure
    const { log, source } = make(['a'], { closeFail: true });
    await assert.rejects(new EventService(source, () => { throw new Error('map'); }).stream().next(), /map/);
    assert.equal(log.closes, 1);
  }
  { // injected throw
    const { log, source } = make(['a', 'b'], { closeFail: true });
    const g = new EventService(source).stream(); await g.next();
    await assert.rejects(g.throw(new Error('inj')), /inj/); assert.equal(log.closes, 1);
  }
  { // close failure propagates on exhaustion and return
    let m = make(['a'], { closeFail: true });
    await assert.rejects((async () => { for await (const _ of new EventService(m.source).stream()); })(), /close/);
    assert.equal(m.log.closes, 1);
    m = make(['a', 'b'], { closeFail: true });
    const g = new EventService(m.source).stream(); await g.next();
    await assert.rejects(g.return(undefined), /close/); assert.equal(m.log.closes, 1);
  }
}
module.exports = main();
